INSERT INTO message (id, content, issuer, chat_id, create_date, update_date, delete_date) VALUES
(1, 'Percebi que fui cobrado duas vezes na fatura deste mês.', 'USER', 1, '2026-07-13 15:39:00', '2026-07-13 15:39:00', NULL),
(2, 'Sinto muito pelo ocorrido, vou verificar o histórico de cobranças da sua conta.', 'AGENT', 1, '2026-07-13 15:45:00', '2026-07-13 15:45:00', NULL),
(3, 'Confirmado, houve uma duplicidade no lançamento da mensalidade.', 'AGENT', 1, '2026-07-13 15:55:00', '2026-07-13 15:55:00', NULL),
(4, 'E como fica o valor cobrado a mais?', 'USER', 1, '2026-07-13 16:10:00', '2026-07-13 16:10:00', NULL),
(5, 'Vou solicitar o estorno do valor duplicado, que deve ser processado em até 5 dias úteis.', 'AGENT', 1, '2026-07-13 16:21:00', '2026-07-13 16:21:00', NULL),
(6, 'Certo, e isso vai aparecer no meu extrato ou vocês creditam na próxima fatura?', 'USER', 1, '2026-07-13 16:29:00', '2026-07-13 16:29:00', NULL),
(7, 'Podemos fazer o estorno direto no cartão ou creditar na próxima fatura, qual prefere?', 'AGENT', 1, '2026-07-13 16:34:00', '2026-07-13 16:34:00', NULL),
(8, 'Prefiro o crédito na próxima fatura, é mais rápido.', 'USER', 1, '2026-07-13 16:44:00', '2026-07-13 16:44:00', NULL),
(9, 'Combinado, já registrei o crédito para a próxima fatura.', 'AGENT', 1, '2026-07-13 16:58:00', '2026-07-13 16:58:00', NULL),
(10, 'Muito obrigado pela solução rápida.', 'USER', 1, '2026-07-13 17:11:00', '2026-07-13 17:11:00', NULL),
(11, 'Disponha! Pedimos desculpas pelo transtorno.', 'AGENT', 1, '2026-07-13 17:24:00', '2026-07-13 17:24:00', NULL),
(12, 'Meu Wi-Fi está caindo de tempos em tempos, várias vezes ao dia.', 'USER', 2, '2026-06-28 12:37:00', '2026-06-28 12:37:00', NULL),
(13, 'Entendo a situação. Vou verificar os registros do seu roteador.', 'AGENT', 2, '2026-06-28 12:49:00', '2026-06-28 12:49:00', NULL),
(14, 'Notei muitas reconexões nas últimas horas. Onde o roteador está posicionado na sua casa?', 'AGENT', 2, '2026-06-28 12:56:00', '2026-06-28 12:56:00', NULL),
(15, 'Ele fica dentro de um armário na sala.', 'USER', 2, '2026-06-28 13:05:00', '2026-06-28 13:05:00', NULL),
(16, 'Esse pode ser o motivo, o sinal fica bloqueado. Recomendo deixá-lo em local aberto e elevado.', 'AGENT', 2, '2026-06-28 13:15:00', '2026-06-28 13:15:00', NULL),
(17, 'Vou tentar colocar em cima do armário então.', 'USER', 2, '2026-06-28 13:24:00', '2026-06-28 13:24:00', NULL),
(18, 'Ótima ideia. Também vou reiniciar o sinal remotamente agora.', 'AGENT', 2, '2026-06-28 13:27:00', '2026-06-28 13:27:00', NULL),
(19, 'Já reposicionei e parece que está mais estável.', 'USER', 2, '2026-06-28 13:32:00', '2026-06-28 13:32:00', NULL),
(20, 'Que bom! Fique de olho nas próximas horas e nos avise se persistir.', 'AGENT', 2, '2026-06-28 13:37:00', '2026-06-28 13:37:00', NULL),
(21, 'Combinado, obrigado pela ajuda!', 'USER', 2, '2026-06-28 13:40:00', '2026-06-28 13:40:00', NULL),
(22, 'Disponha, estamos à disposição.', 'AGENT', 2, '2026-06-28 13:47:00', '2026-06-28 13:47:00', NULL),
(23, 'Só mais uma dúvida, isso pode acontecer novamente?', 'USER', 2, '2026-06-28 13:49:00', '2026-06-28 13:49:00', NULL),
(24, 'É pouco provável, mas caso ocorra, é só entrar em contato conosco novamente.', 'AGENT', 2, '2026-06-28 14:00:00', '2026-06-28 14:00:00', NULL),
(25, 'Entendido, vou ficar de olho por aqui.', 'USER', 2, '2026-06-28 14:10:00', '2026-06-28 14:10:00', NULL),
(26, 'Boa noite, gostaria de saber quais planos de internet vocês têm disponíveis para minha região.', 'USER', 3, '2026-07-12 11:03:00', '2026-07-12 11:03:00', NULL),
(27, 'Boa noite! Temos os planos de 300MB, 500MB e 1GB disponíveis para o seu endereço.', 'AGENT', 3, '2026-07-12 11:16:00', '2026-07-12 11:16:00', NULL),
(28, 'Qual a diferença de valor entre o de 300MB e o de 500MB?', 'USER', 3, '2026-07-12 11:28:00', '2026-07-12 11:28:00', NULL),
(29, 'O plano de 300MB custa R$ 99,90 e o de 500MB custa R$ 129,90 por mês.', 'AGENT', 3, '2026-07-12 11:30:00', '2026-07-12 11:30:00', NULL),
